import { NextResponse } from "next/server";
import { requestPasswordReset, resetPassword } from "@/lib/users";

// POST /api/password-reset — request a reset email for the given address.
// Always returns 200 with a generic message so this endpoint can't be used
// to enumerate registered emails.
export async function POST(request: Request) {
  const body = await request.json().catch(() => null);

  if (!body || typeof body.email !== "string") {
    return NextResponse.json({ error: "email is required" }, { status: 400 });
  }

  await requestPasswordReset(body.email);

  return NextResponse.json({
    message: "If that email is registered, a reset link has been sent.",
  });
}

// PUT /api/password-reset — complete a reset using the token from the email.
export async function PUT(request: Request) {
  const body = await request.json().catch(() => null);

  if (
    !body ||
    typeof body.token !== "string" ||
    typeof body.password !== "string" ||
    body.password.length < 8
  ) {
    return NextResponse.json(
      { error: "token and password (min 8 chars) are required" },
      { status: 400 }
    );
  }

  try {
    await resetPassword(body.token, body.password);
    return NextResponse.json({ message: "Password updated." });
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "Failed to reset password" },
      { status: 400 }
    );
  }
}

